(1, 'Cine Colombia', 'Centro Comercial Terra Plaza', 'Popayán'),
(2, 'Royal Films', 'Centro Comercial Campanario', 'Popayán');
INSERT INTO `peliculas` (`id_pelicula`, `titulo`, `titulo_originalPelicula`, `sinopsis`, `anio`, `actoresPelicula`, `generoPelicula`, `idiomaPelicula`, `poster`, `lema`, `trailer`) VALUES
(1, 'Super Mario Galaxy la película', 'The Super Mario Galaxy Movie', 'Secuela de \'Super Mario Bros: La película\', basada en la saga \'Mario Galaxy\'. Los hermanos Mario y Luigi y la princesa Peach emprenden una aventura hasta los confines del espacio y a través de la galaxia.', 2026, '[{\"nombre\": \"Chris Pratt\", \"personaje\": \"Mario (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/cRH6HPAQ98PlOwwEvhYO4CM9lwu.jpg\"}, {\"nombre\": \"Anya Taylor-Joy\", \"personaje\": \"Princess Peach (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/qYNofOjlRke2MlJVihmJmEdQI4v.jpg\"}, {\"nombre\": \"Charlie Day\", \"personaje\": \"Luigi (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/c0HNhjChGybnHa4eoLyqO4dDu1j.jpg\"}]', 'Otro', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/4Js0gYWxuvTN6b8iAaSF1cSQzBs.jpg', '', 'https://www.youtube.com/watch?v=Hz57G2KaAp8'),
(2, 'Intercambiados', 'Swapped', 'Una pequeña criatura del bosque intercambia el cuerpo con un majestuoso pájaro del valle, lo que los obliga a colaborar para sobrevivir a la aventura más salvaje de sus vidas.', 2026, '[{\"nombre\": \"Michael B. Jordan\", \"personaje\": \"Ollie (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/sMBpav8cK7t7Nk0yf4tuNOqNUyW.jpg\"}, {\"nombre\": \"Juno Temple\", \"personaje\": \"Ivy (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/n20TNExAma6q9iVcWtPRxLl7pEc.jpg\"}, {\"nombre\": \"Tracy Morgan\", \"personaje\": \"Boogle / Firewolf (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/ec0OJVbs6NZKMbS1yiCAJKjeoJf.jpg\"}]', 'Otro', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/i89vUDwNhAEWUZSFYITSiv1RIbK.jpg', '', 'https://www.youtube.com/watch?v=oZlnTUemKPU'),
(3, 'Depredador dominante', 'Apex', 'Una mujer en duelo se adentra en la naturaleza de Australia para ponerse a prueba y queda atrapada en un juego mortal con un astuto asesino que la considera su presa.', 2026, '[{\"nombre\": \"Charlize Theron\", \"personaje\": \"Sasha\", \"foto\": \"https://image.tmdb.org/t/p/w200/gd7ShD0yt4bsR2STeQ19KQ6hvXL.jpg\"}, {\"nombre\": \"Taron Egerton\", \"personaje\": \"Ben\", \"foto\": \"https://image.tmdb.org/t/p/w200/uCaPhyKAQIfEzAWWCYIrO2004CB.jpg\"}, {\"nombre\": \"Eric Bana\", \"personaje\": \"Tommy\", \"foto\": \"https://image.tmdb.org/t/p/w200/l9yoDgw3YFC2gMD1HTo5djGOwSY.jpg\"}]', 'Accion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/mV7uFS1U8iP0p4CcXZp4znBVpch.jpg', '', 'https://www.youtube.com/watch?v=cPtiCoSTeug'),
(4, 'Malèna', 'Malèna', 'Malena es la belleza más encantadora e irresistible de Castelcuto, un aburrido pueblo de la soleada costa siciliana. Es nueva en la población y estando su marido en la guerra, cada paseo que da por el pueblo se convierte en un espectáculo, acompañado por las lujuriosas miradas de los hombres de la localidad y de los resentidos cotilleos de sus envidiosas esposas. Un ejército de flacos adolescentes en bicicleta la sigue allí donde vaya, con la única intención de observar su exquisita y arquetípica belleza. Entre ellos se encuentra Renato Amoroso, un chico de trece años con mucha imaginación que lleva su deseo a unos límites inesperados de obsesiva fantasía.', 2000, '[{\"nombre\": \"Monica Bellucci\", \"personaje\": \"Malèna Scordia\", \"foto\": \"https://image.tmdb.org/t/p/w200/7g3k3u2gZpE7XU8GRYwHDuN1jlM.jpg\"}, {\"nombre\": \"Giuseppe Sulfaro\", \"personaje\": \"Renato Amoroso\", \"foto\": \"https://image.tmdb.org/t/p/w200/n2dGRXym6gJwwwkDt5IUjTnAHVt.jpg\"}, {\"nombre\": \"Luciano Federico\", \"personaje\": \"Renato\'s Father\", \"foto\": \"https://image.tmdb.org/t/p/w200/tkZN8uWDtnoMkjaJ1GCQoBKc7eo.jpg\"}]', 'Drama', 'Otro', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/p1DmuHTnvhsWFvWX0xnMWrLBVZ5.jpg', 'Demasiado joven para ser viuda, demasiado hermosa para estar sola.', ''),
(5, 'SEND HELP (Enviad ayuda)', 'Send Help', 'Después de que un accidente de avión deje varados en una isla remota a una competente empleada y a su insoportable jefe, ella deberá utilizar sus habilidades de supervivencia para mantenerlos a ambos con vida, a pesar de su difícil relación.', 2026, '[{\"nombre\": \"Rachel McAdams\", \"personaje\": \"Linda Liddle\", \"foto\": \"https://image.tmdb.org/t/p/w200/2zyOjda95OfAAsJvuwTV0UaznPZ.jpg\"}, {\"nombre\": \"Dylan O\'Brien\", \"personaje\": \"Bradley Preston\", \"foto\": \"https://image.tmdb.org/t/p/w200/xN3GdvIlqsR838gDoblhPH0numP.jpg\"}, {\"nombre\": \"Edyll Ismail\", \"personaje\": \"Zuri\", \"foto\": \"https://image.tmdb.org/t/p/w200/4JNIAlJXlw1HTF2log6GUeErDcT.jpg\"}]', 'Terror', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/qXZZtyzuTX3KMfSLssCR6J0mODd.jpg', 'Esta es Linda Liddle... Trabaja en estrategia y planificación... Ahora es la jefa.', 'https://www.youtube.com/watch?v=OTMeWZNhE64'),
(6, 'El diablo viste de Prada', 'The Devil Wears Prada', 'En el vertiginoso mundo de la moda en Nueva York, la revista \'Runway\' es el Santo Grial. Dirigida con puño de hierro y elegante manicura por Miranda Priestly, trabajar en ella es un temible reto para todo aquel que quiera triunfar en ese mundo. Hacerlo como ayudante de Miranda podría abrirle cualquier puerta a Andy Sachs, recientemente graduada. Pero ella es una chica que destaca por su desaliño dentro del pequeño ejército de guapísimas redactoras de la revista. Andy comprende muy pronto que para triunfar en ese negocio va a necesitar algo más que iniciativa y determinación. Y la prueba definitiva está delante de ella, vestida de Prada de pies a cabeza.  Es una mierda de película!!', 2006, '[{\"nombre\": \"Meryl Streep\", \"personaje\": \"Miranda Priestly\", \"foto\": \"https://image.tmdb.org/t/p/w200/g5cVxQBAQ3AXt3LhdBXtbbN47Uc.jpg\"}, {\"nombre\": \"Anne Hathaway\", \"personaje\": \"Andy Sachs\", \"foto\": \"https://image.tmdb.org/t/p/w200/s6tflSD20MGz04ZR2R1lZvhmC4Y.jpg\"}, {\"nombre\": \"Emily Blunt\", \"personaje\": \"Emily\", \"foto\": \"https://image.tmdb.org/t/p/w200/5nCSG5TL1bP1geD8aaBfaLnLLCD.jpg\"}]', 'Drama', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/mRzLk61g46qpik5yt4MOaFiNyVm.jpg', 'El trabajo de tus sueños viene con una jefa diabólica.', 'https://www.youtube.com/watch?v=bb3NblYZwQU'),
(7, 'Mortal Kombat II', 'Mortal Kombat II', 'Los campeones favoritos de los fans, ahora acompañados por el propio Johnny Cage, se enfrentan cara a cara en la definitiva y sangrienta batalla a muerte para vencer al oscuro régimen de Shao Kahn, que amenaza la existencia del Reino de la Tierra y a sus defensores.', 2026, '[{\"nombre\": \"Karl Urban\", \"personaje\": \"Johnny Cage\", \"foto\": \"https://image.tmdb.org/t/p/w200/6CkZLwEJxfqqcJHyeXegMAvOlPh.jpg\"}, {\"nombre\": \"Adeline Rudolph\", \"personaje\": \"Kitana\", \"foto\": \"https://image.tmdb.org/t/p/w200/sWjjm53MeVrpQH2dxtFD3gfEt3v.jpg\"}, {\"nombre\": \"Jessica McNamee\", \"personaje\": \"Sonya Blade\", \"foto\": \"https://image.tmdb.org/t/p/w200/sKgsW78FCDWAes0SeCp5lgq3eou.jpg\"}]', 'Accion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/ivVKHht5jutNGnObn1y5sSDrAXn.jpg', '', 'https://www.youtube.com/watch?v=nUfwLpIiWCU'),
(8, 'Tu corazón se romperá', 'Твоё сердце будет разбито', 'Polina, una estudiante de secundaria, encuentra un salvavidas inesperado frente al acoso que sufre en su nuevo instituto. Para frenar el bullying, sella un pacto con Bars, el cabecilla de los abusadores: él fingirá ser su novio y se convertirá en su protector, pero a cambio, ella tendrá que obedecerle en todo lo que él le pida.  Lo que empieza como un juego de supervivencia se complica cuando la química entre los dos se vuelve real. Sin embargo, su historia tiene los días contados: tanto sus familias como sus propios compañeros harán lo imposible por dinamitar una relación que nadie aprueba.', 2026, '[{\"nombre\": \"Даниэль Вегас\", \"personaje\": \"Барс\", \"foto\": \"https://image.tmdb.org/t/p/w200/t9AFZX1rpTt59npITX2GY3JgySd.jpg\"}, {\"nombre\": \"Вероника Журавлёва\", \"personaje\": \"Полина\", \"foto\": \"https://image.tmdb.org/t/p/w200/bvlry6DeiYkm0onAZhonlpl4J7.jpg\"}, {\"nombre\": \"Иван Трушин\", \"personaje\": \"Лэйм\", \"foto\": \"https://image.tmdb.org/t/p/w200/8DWSEUJnxlr7kTP0O8iOSnsqbcs.jpg\"}]', 'Romance', 'Otro', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/iGpMm603GUKH2SiXB2S5m4sZ17t.jpg', '', ''),
(9, 'Michael', 'Michael', 'El viaje de Michael Jackson más allá de la música, desde el descubrimiento de su extraordinario talento como líder de los Jackson Five hasta convertirse en una visionaria estrella cuya ambición creativa despertó un incansable afán por consagrarse como el mayor icono de la industria del entretenimiento.', 2026, '[{\"nombre\": \"Jaafar Jackson\", \"personaje\": \"Michael Jackson\", \"foto\": \"https://image.tmdb.org/t/p/w200/tVSzFjQxOrLOcvnzFto0772Q9Bw.jpg\"}, {\"nombre\": \"Colman Domingo\", \"personaje\": \"Joseph Jackson\", \"foto\": \"https://image.tmdb.org/t/p/w200/t0cgfvtA7Thxnrtj5baRi656zlc.jpg\"}, {\"nombre\": \"Nia Long\", \"personaje\": \"Katherine Jackson\", \"foto\": \"https://image.tmdb.org/t/p/w200/heVQkCGKUuKKRjRJaZIBrEKGhYA.jpg\"}]', 'Otro', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/2uK36ujoDXOfNiJ5Yp3raVprB51.jpg', 'Descubre el origen de un Rey.', 'https://www.youtube.com/watch?v=o1HQSh6zZ8s'),
(10, 'Noche de bodas 2', 'Ready or Not 2: Here I Come', 'Momentos después de sobrevivir a un ataque de la familia Le Domas, Grace descubre que ha alcanzado el siguiente nivel del juego, y esta vez acompañada por su hermana Faith, con quien mantiene una relación distante. Grace tiene una oportunidad para sobrevivir, mantener con vida a su hermana y reclamar el Alto Trono del Consejo que controla el mundo. Cuatro familias rivales la persiguen para hacerse con el trono, y quien gane lo gobernará todo.', 2026, '[{\"nombre\": \"Samara Weaving\", \"personaje\": \"Grace MacCaulley\", \"foto\": \"https://image.tmdb.org/t/p/w200/7ThO37CpqkBRgrosep0ROVs2q5s.jpg\"}, {\"nombre\": \"Kathryn Newton\", \"personaje\": \"Faith MacCaulley\", \"foto\": \"https://image.tmdb.org/t/p/w200/zjecUqb2v2bXPNBdjkwxF7zIWmW.jpg\"}, {\"nombre\": \"Elijah Wood\", \"personaje\": \"The Lawyer\", \"foto\": \"https://image.tmdb.org/t/p/w200/ayARmqAe9Aab1zg6FjJG0u9MEBo.jpg\"}]', 'Terror', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/nDXKMOLJuBUKhYmHAY9qJdikuAq.jpg', '', 'https://www.youtube.com/watch?v=1v-iZS1SPmc'),
(11, 'Hoppers', 'Hoppers', 'Una amante de los animales aprovecha la oportunidad de utilizar una tecnología que coloca su conciencia en un castor robótico, descubriendo misterios dentro del mundo animal que van más allá de lo que podría haber imaginado.', 2026, '[{\"nombre\": \"Piper Curda\", \"personaje\": \"Mabel (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/oyitEBcracNWMuF8Frhsqkjgzuc.jpg\"}, {\"nombre\": \"Bobby Moynihan\", \"personaje\": \"King George (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/gOvwNz5joi5yWJ7dAhuF8WA2aas.jpg\"}, {\"nombre\": \"Jon Hamm\", \"personaje\": \"Mayor Jerry Generazzo (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/mrXE5fZbEDPc7BEE5G21J6qrwzi.jpg\"}]', 'Otro', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/4Z0E1W7YvQ0aVtgj7KKtktb9ukd.jpg', '', 'https://www.youtube.com/watch?v=bv0sKzFvpmo'),
(12, 'Tayuan 2', 'Tayuan 2', '', 2026, '[{\"nombre\": \"Ashley Lopez\", \"personaje\": \"Rhea\", \"foto\": \"https://image.tmdb.org/t/p/w200/pRIF389pP8fCmkp7wlOusY9AlMQ.jpg\"}, {\"nombre\": \"Marco Mora\", \"personaje\": \"Marco\", \"foto\": \"https://image.tmdb.org/t/p/w200/9taPM0O5fMHleKYI21kMnW5VC4N.jpg\"}, {\"nombre\": \"Chester Grecia\", \"personaje\": \"Rico\", \"foto\": \"https://image.tmdb.org/t/p/w200/4wICQfl1RbrL6C0HhTtW9Yic8kE.jpg\"}]', 'Drama', 'Otro', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/gkHNa8q3RNhgj2EMuoYWJUHsMa6.jpg', '', ''),
(13, 'Sangre asesina', 'เลือดรัก นักฆ่า', 'A una mujer le espera una bala con su nombre por culpa de su extraño grupo sanguíneo, pero encuentra cobijo en los brazos del asesino al que ama, y juntos luchan por sobrevivir.', 2026, '[{\"nombre\": \"พิมพ์ชนก ลือวิเศษไพบูลย์\", \"personaje\": \"Lhan\", \"foto\": \"https://image.tmdb.org/t/p/w200/1dAa0G7gG3KbeF66HOof4DPXrpX.jpg\"}, {\"nombre\": \"ธนภพ ลีรัตนขจร\", \"personaje\": \"Pran\", \"foto\": \"https://image.tmdb.org/t/p/w200/zZCYpbtAe4axyySy0TYS8eICujw.jpg\"}, {\"nombre\": \"ศิวกร อดุลสุทธิกุล\", \"personaje\": \"M\", \"foto\": \"https://image.tmdb.org/t/p/w200/tbE7j3kwPCW6Yj3WQPZFtL9EasR.jpg\"}]', 'Accion', 'Otro', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/16TvbhCP8CfiGEbxcbtQLYWO6WG.jpg', '', ''),
(14, 'Avatar: Fuego y ceniza', 'Avatar: Fire and Ash', 'Jake Sully y Neytiri enfrentan una nueva amenaza en Pandora: los Ash People, una tribu Na\'vi violenta y sedienta de poder, liderada por la implacable Varang. Tras la devastadora guerra contra la RDA y la pérdida de su hijo mayor, la familia de Jake deberá luchar por su supervivencia y el futuro de Pandora en un conflicto que llevará a los personajes a sus límites emocionales y físicos. Con nuevos y antiguos aliados, esta épica visual y emocional redefine el destino de un mundo al borde del abismo.', 2025, '[{\"nombre\": \"Sam Worthington\", \"personaje\": \"Jake\", \"foto\": \"https://image.tmdb.org/t/p/w200/mflBcox36s9ZPbsZPVOuhf6axaJ.jpg\"}, {\"nombre\": \"Zoe Saldaña\", \"personaje\": \"Neytiri\", \"foto\": \"https://image.tmdb.org/t/p/w200/iOVbUH20il632nj2v01NCtYYeSg.jpg\"}, {\"nombre\": \"Sigourney Weaver\", \"personaje\": \"Kiri\", \"foto\": \"https://image.tmdb.org/t/p/w200/wTSnfktNBLd6kwQxgvkqYw6vEon.jpg\"}]', 'Ciencia Ficcion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/4n1U0Mwn7djux6VKNYDRWPgS2x6.jpg', '', 'https://www.youtube.com/watch?v=ndYS51j7G3o'),
(15, 'Hot Girls Wanted', 'Hot Girls Wanted', 'Gracias a Internet, miles de jóvenes estadounidenses están entrando en el “amateur” mundo del porno, en cumplimiento de una demanda creciente de aspirantes a estrellas estilo “chica de al lado”. ‘Hot Girls Wanted’ sigue a una de esas chicas, deseosa de dejar la vida de pueblo pequeño en busca de la libertad y la fama.', 2015, '[{\"nombre\": \"Stella May\", \"personaje\": \"Self\", \"foto\": \"https://image.tmdb.org/t/p/w200/xiRz5z9Y9DJanzHU5XaYTLRoXHM.jpg\"}, {\"nombre\": \"Brian Omally\", \"personaje\": \"Self - Founder of Hussie Models\", \"foto\": \"https://image.tmdb.org/t/p/w200/fq5Ebw9Obu8zYSqqD220AfVJOL9.jpg\"}, {\"nombre\": \"Ava Taylor\", \"personaje\": \"Self\", \"foto\": \"https://image.tmdb.org/t/p/w200/ov3ElY5s1t1kmPdVqBKPvW5j7RC.jpg\"}]', 'Documental', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/75ot83QOkc02vujyzmIbumQCU6Y.jpg', '', ''),
(16, 'El diablo viste de Prada 2', 'The Devil Wears Prada 2', 'Sigue la lucha de Miranda Priestly contra Emily Charlton, su ex asistente convertida en ejecutiva rival, mientras compiten por los ingresos por publicidad en medio de la decadencia de los medios impresos y Miranda se acerca a la jubilación.', 2026, '[{\"nombre\": \"Meryl Streep\", \"personaje\": \"Miranda Priestly\", \"foto\": \"https://image.tmdb.org/t/p/w200/g5cVxQBAQ3AXt3LhdBXtbbN47Uc.jpg\"}, {\"nombre\": \"Anne Hathaway\", \"personaje\": \"Andy Sachs\", \"foto\": \"https://image.tmdb.org/t/p/w200/s6tflSD20MGz04ZR2R1lZvhmC4Y.jpg\"}, {\"nombre\": \"Emily Blunt\", \"personaje\": \"Emily Charlton\", \"foto\": \"https://image.tmdb.org/t/p/w200/5nCSG5TL1bP1geD8aaBfaLnLLCD.jpg\"}]', 'Comedia', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/sz687EF7yJMS4VNEdHKT9ebkhA9.jpg', '', 'https://www.youtube.com/watch?v=IQD3qh7te2o'),
(17, 'Venganza', 'Venganza', 'Carlos y Miguel son dos soldados de élite de las fuerzas especiales mexicanas y mejores amigos cuyas vidas cambian para siempre cuando Carlos es testigo del brutal asesinato de su esposa por manos de un despiadado asesino. Determinado a buscar justicia, emprende un peligroso viaje de venganza, alimentado por el dolor y armado con una lotería que cambia su vida.', 2026, '[{\"nombre\": \"Omar Chaparro\", \"personaje\": \"Carlos Estrada\", \"foto\": \"https://image.tmdb.org/t/p/w200/fAIDrbtyHBcDDbRdRZ3bvNesKU7.jpg\"}, {\"nombre\": \"Alejandro Speitzer\", \"personaje\": \"Miguel Díaz\", \"foto\": \"https://image.tmdb.org/t/p/w200/cV95e8sHliYBnjdz1OpZYqAywL7.jpg\"}, {\"nombre\": \"Paola Nuñez\", \"personaje\": \"Cnel. Gabriela Rangel\", \"foto\": \"https://image.tmdb.org/t/p/w200/5k8tBBvoV43iK6u0k2YUSVXPmuK.jpg\"}]', 'Accion', 'Espanol', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/ggJGx8fwwy21gEIXYusIlHcUn8z.jpg', '', ''),
(18, 'Te van a matar', 'They Will Kill You', 'Una mujer acepta un trabajo como ama de llaves en un rascacielos de Nueva York, sin conocer el historial de desapariciones del edificio. Pronto se da cuenta de que la comunidad está rodeada de misterio.', 2026, '[{\"nombre\": \"Zazie Beetz\", \"personaje\": \"Asia Reaves\", \"foto\": \"https://image.tmdb.org/t/p/w200/sgxzT54GnvgeMnOZgpQQx9csAdd.jpg\"}, {\"nombre\": \"Myha\'la\", \"personaje\": \"Maria Reaves\", \"foto\": \"https://image.tmdb.org/t/p/w200/hRc3igngt5dkpM08i0a3z7gkYWa.jpg\"}, {\"nombre\": \"Patricia Arquette\", \"personaje\": \"Lily Woodhouse\", \"foto\": \"https://image.tmdb.org/t/p/w200/jeThSouMatiuRiLkjDvSBLHpmq0.jpg\"}]', 'Accion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/9dEn8a12dqkQw48zxQhPcpQ7D5W.jpg', '', 'https://www.youtube.com/watch?v=7JZtKhkeGXo'),
(19, 'GOAT: Como cabras', 'GOAT', 'Will es una pequeña cabra con grandes sueños que recibe una oportunidad única en la vida para unirse a los profesionales y jugar al rugebol, un deporte de alta intensidad, mixto y de contacto total dominado por los animales más rápidos y feroces del mundo. A los nuevos compañeros de equipo de Will no les entusiasma tener a una cabrita en su plantilla, pero Will está decidido a revolucionar el deporte y demostrar de una vez por todas que «¡los pequeños saben jugar!».', 2026, '[{\"nombre\": \"Caleb McLaughlin\", \"personaje\": \"Will Harris (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/4jVS3EziBn7bf97ErxkW7jsdiLM.jpg\"}, {\"nombre\": \"Gabrielle Union\", \"personaje\": \"Jett Fillmore (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/toeSCybsYufRKfgz77AKy4C8axD.jpg\"}, {\"nombre\": \"Stephen Curry\", \"personaje\": \"Lenny Williamson (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/dmLZdGhZkCYktooIp8iqXhAvoWz.jpg\"}]', 'Animacion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/l8Y8o3RpFg54gmQQ8GVaxVroFmY.jpg', 'Nunca eres demasiado pequeño para soñar en grande.', 'https://www.youtube.com/watch?v=q56pw-zFDP8'),
(20, 'Criaturas luminosas', 'Remarkably Bright Creatures', 'En este drama, basado en el bestseller homónimo, una viuda forja un vínculo con un pulpo muy listo y un joven a la deriva mientras trabaja de noche en un pequeño acuario.', 2026, '[{\"nombre\": \"Sally Field\", \"personaje\": \"Tova Sullivan\", \"foto\": \"https://image.tmdb.org/t/p/w200/iMeq1j9Xwvaf6PbTJ0FQz69fpuA.jpg\"}, {\"nombre\": \"Lewis Pullman\", \"personaje\": \"Cameron Cassmore\", \"foto\": \"https://image.tmdb.org/t/p/w200/ws3WR1F2DfjtLLbK8XOGHEZbX1A.jpg\"}, {\"nombre\": \"Colm Meaney\", \"personaje\": \"Ethan Mack\", \"foto\": \"https://image.tmdb.org/t/p/w200/guL6RJdlRMtOJN3LoaY3G8hG4Rd.jpg\"}]', 'Drama', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/aNixJoh0U4kN85YM6vPyVZL6ALF.jpg', '', 'https://www.youtube.com/watch?v=4qqbNVMCJBc'),
(21, 'Proyecto Salvación', 'Project Hail Mary', 'El profesor de ciencias Ryland Grace se despierta en una nave espacial a años luz de casa sin recordar quién es ni cómo ha llegado hasta allí. A medida que recupera la memoria, empieza a descubrir su misión: resolver el enigma de la misteriosa sustancia que provoca la extinción del sol. Deberá recurrir a sus conocimientos científicos y a sus ideas poco ortodoxas para salvar todo lo que hay en la Tierra de la extinción... pero una amistad inesperada significa que quizá no tenga que hacerlo solo.', 2026, '[{\"nombre\": \"Ryan Gosling\", \"personaje\": \"Ryland Grace\", \"foto\": \"https://image.tmdb.org/t/p/w200/k50021gkK92Lx6m99pBy6FUOvNf.jpg\"}, {\"nombre\": \"Sandra Hüller\", \"personaje\": \"Eva Stratt\", \"foto\": \"https://image.tmdb.org/t/p/w200/jQfKXVCPTH9KEnzHHU4QemCnlMe.jpg\"}, {\"nombre\": \"James Ortiz\", \"personaje\": \"Rocky (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/zYYDXniHb36mjG7xK59r9IoOKvt.jpg\"}]', 'Ciencia Ficcion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/7lwOTxajURKEWO6gI370NTrVdBO.jpg', '', 'https://www.youtube.com/watch?v=in-lUuKi0eE'),
(22, 'La leyenda de Aang: El último Airbender', 'Avatar Aang: The Last Airbender', 'Película de animación que seguirá a Aang y sus amigos, ahora como jóvenes adultos, varios años después de los acontecimientos del final de \'Avatar: The Last Airbender\'.', 2026, '[{\"nombre\": \"Eric Nam\", \"personaje\": \"Aang (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/gEH0b5q9tupL49dmUFkjm9dnxP2.jpg\"}, {\"nombre\": \"Dave Bautista\", \"personaje\": \"Tagah (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/snk6JiXOOoRjPtHU5VMoy6qbd32.jpg\"}, {\"nombre\": \"Jessica Matten\", \"personaje\": \"Katara (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/EQsPxsav8AZmaeT3mpU3Evilee.jpg\"}]', 'Animacion', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/iMsORWhD8MawINagL6kvpDVAtS.jpg', '', ''),
(23, 'El drama', 'The Drama', 'Una pareja, en los días previos a su boda, se enfrenta a una crisis cuando unas inesperadas revelaciones desbaratan lo que uno de ellos creía saber sobre el otro.', 2026, '[{\"nombre\": \"Zendaya\", \"personaje\": \"Emma Harwood\", \"foto\": \"https://image.tmdb.org/t/p/w200/uD5a0CsVbR0phlUvHXLlKntAIXS.jpg\"}, {\"nombre\": \"Robert Pattinson\", \"personaje\": \"Charlie Thompson\", \"foto\": \"https://image.tmdb.org/t/p/w200/3qZ09UE7lN6AtorfXFRYpEtSY93.jpg\"}, {\"nombre\": \"Mamoudou Athie\", \"personaje\": \"Mike\", \"foto\": \"https://image.tmdb.org/t/p/w200/ycUbhfZRKC8MtNK9oMwscRsl3uM.jpg\"}]', 'Romance', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/zgfBYGYCNcOZ51JDbr6tm45H8y0.jpg', '', 'https://www.youtube.com/watch?v=pn8-dhxHVX8'),
(24, 'Guardianes de la noche: Kimetsu no Yaiba La fortaleza infinita', '劇場版「鬼滅の刃」無限城編 第一章 猗窩座再来', 'El Cuerpo de Cazadores de Demonios se enfrenta a los Doce Kizuki restantes antes de enfrentarse a Muzan en el Castillo del Infinito para derrotarlo de una vez por todas.', 2025, '[{\"nombre\": \"Natsuki Hanae\", \"personaje\": \"Tanjiro Kamado (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/alTb0DlcPIbcwM08WSmxFai58sd.jpg\"}, {\"nombre\": \"Takahiro Sakurai\", \"personaje\": \"Giyu Tomioka (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/8s8owcKmpRAuhzEGjSdRpztthUg.jpg\"}, {\"nombre\": \"Akira Ishida\", \"personaje\": \"Akaza (voice)\", \"foto\": \"https://image.tmdb.org/t/p/w200/jnW2Gn2NlR2uwOCeyOuzypnTmkH.jpg\"}]', 'Animacion', 'Japones', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/iWLV12z9oexSRLz2WKyqCZbKoPA.jpg', '¡Vamos a pasarlo bien!', 'https://www.youtube.com/watch?v=X3E4zogzWsY'),
(25, '911: Llamada infernal', 'Bodycam', 'Durante una llamada rutinaria por disturbios domésticos, un trágico accidente lleva a dos oficiales de policía a una pesadilla implacable que revela la existencia de un culto aterrador.', 2026, '[{\"nombre\": \"Jaime M. Callica\", \"personaje\": \"Officer Jackson\", \"foto\": \"https://image.tmdb.org/t/p/w200/bMdYe1mrsvLp638lNqTqQELroNr.jpg\"}, {\"nombre\": \"Sean Rogerson\", \"personaje\": \"Officer Bryce\", \"foto\": \"https://image.tmdb.org/t/p/w200/AeU4FinI8HOEh7CFhx99YTS5FkY.jpg\"}, {\"nombre\": \"Catherine Lough Haggquist\", \"personaje\": \"Ally Jackson\", \"foto\": \"https://image.tmdb.org/t/p/w200/3q6uhNYa7Dapl09YtqVrwndmj1l.jpg\"}]', 'Terror', 'Ingles', 'https://image.tmdb.org/t/p/w600_and_h900_bestv2/aOIXYOwB97ioUnhHzwnyCRxwVBe.jpg', '', ''),
